package com.hospital.service.impl;
import com.hospital.entity.Patient; import com.hospital.repository.PatientRepository; import com.hospital.repository.AppointmentRepository; import com.hospital.repository.MedicalRecordRepository; import com.hospital.repository.RoomAllocationRepository; import com.hospital.service.PatientService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PatientServiceImpl extends AbstractCrudService<Patient> implements PatientService {
 private final PatientRepository patients; private final AppointmentRepository appointments; private final MedicalRecordRepository records; private final RoomAllocationRepository allocations;
 public PatientServiceImpl(PatientRepository patients,AppointmentRepository appointments,MedicalRecordRepository records,RoomAllocationRepository allocations){super(patients);this.patients=patients;this.appointments=appointments;this.records=records;this.allocations=allocations;}
 @Override @Transactional public Patient create(Patient p){p.setPatientId(null);validate(p);return patients.save(p);}
 @Override @Transactional public Patient update(Integer id,Patient p){patients.lockById(id).orElseThrow(()->new com.hospital.exception.ResourceNotFoundException("Patient not found: "+id));validate(p);p.setPatientId(id);return patients.save(p);}
 @Override @Transactional public void delete(Integer id){patients.lockById(id).orElseThrow(()->new com.hospital.exception.ResourceNotFoundException("Patient not found: "+id));if(appointments.countByPatientId(id)>0||records.countByPatientId(id)>0||allocations.countByPatientId(id)>0)throw new IllegalArgumentException("Patient cannot be deleted while appointments, records, or room allocations reference them.");patients.deleteById(id);}
 private void validate(Patient p){if(p.getPatientName()==null||p.getPatientName().isBlank()||p.getGender()==null||p.getGender().isBlank()||p.getAdmissionDate()==null||p.getAilment()==null||p.getAilment().isBlank()||p.getAssignedDoctor()==null||p.getAssignedDoctor().isBlank())throw new IllegalArgumentException("Patient name, age, gender, admission date, ailment, and assigned doctor are required.");if(p.getAge()==null||p.getAge()<0||p.getAge()>120)throw new IllegalArgumentException("Patient age is required and must be between 0 and 120.");
String gender=p.getGender().trim();if(!gender.equalsIgnoreCase("Male")&&!gender.equalsIgnoreCase("Female")&&!gender.equalsIgnoreCase("Other"))throw new IllegalArgumentException("Gender must be Male, Female, or Other.");}
}
